import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { EFFECTS, effectControls, effectDuration, effectInputs, effectTags, findEffects, getEffect, type EffectQuery } from "./index.js";
import { metaOf, packMeta, type EffectMeta } from "./meta.js";
import { packLayerEntry } from "./layer-index.js";
import { EFFECT_CATEGORY_GROUPS, type EffectDefinition } from "./types.js";

/**
 * The lazy catalog's generated files come from the catalog itself. When the
 * catalog changes, this test fails until they are written again with
 * `pnpm catalog:meta` (which runs it with UPDATE_CATALOG_META=1).
 */
const META_FILE = resolve("src/catalog/meta.generated.json");
const MODULES_FILE = resolve("src/catalog/modules.generated.ts");
const LAYERS_FILE = resolve("src/catalog/layer-index.generated.ts");
/** The flair-use skill's effect index: one Markdown file per category group. */
const INDEX_DIR = resolve("skills/flair-use/references/effects");

declare global {
  interface ImportMeta {
    /** Vite's module glob, which Vitest runs. */
    glob<T>(patterns: string[], options: { eager: true }): Record<string, T>;
  }
}

// Every catalog module, eagerly, to find which one holds each effect.
const MODULES = import.meta.glob<Record<string, unknown>>(["./*.ts", "./shaders/*.ts", "!./*.test.ts", "!./index.ts", "!./lazy.ts", "!./meta.ts", "!./query.ts", "!./modules.generated.ts"], { eager: true });

function effectsIn(module: Record<string, unknown>): EffectDefinition[] {
  const isEffect = (v: unknown): v is EffectDefinition => !!v && typeof v === "object" && "id" in v && "kind" in v;
  return Object.values(module).flatMap((v) => (Array.isArray(v) ? v.filter(isEffect) : isEffect(v) ? [v] : []));
}

/** The module each effect is loaded from: of the modules that export it, the one with the fewest effects. */
function moduleOf(): Map<string, string> {
  const found = new Map<string, string>();
  const ids = new Set(EFFECTS.map((e) => e.id));
  const sizes = Object.entries(MODULES)
    .map(([path, module]) => ({ key: path.replace(/^\.\//, "").replace(/\.ts$/, ""), effects: effectsIn(module).filter((e) => ids.has(e.id) && getEffect(e.id) === e) }))
    .filter((m) => m.effects.length)
    .sort((a, b) => a.effects.length - b.effects.length || a.key.localeCompare(b.key));
  for (const { key, effects } of sizes) for (const e of effects) if (!found.has(e.id)) found.set(e.id, key);
  return found;
}

/** A group's file name in the effect index: "Particles & FX" → `particles-fx.md`. */
const indexFile = (group: string) => `${group.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}.md`;

/** One effect as a line of the skill's effect index: id, kind, what it looks like, takes, presets and tags. */
function indexLine(m: EffectMeta): string {
  const kind = m.kind === "camera" ? `camera move, ${m.role}` : m.kind;
  const takes = m.inputs.accepts.length ? ` Takes ${m.inputs.accepts.join(", ")}.` : "";
  const words = m.inputs.texts.filter((t) => t.holds === "copy").map((t) => `\`${t.name}\``);
  const wordsIn = words.length ? ` Words go in ${words.join(", ")}.` : "";
  const answers = m.inputs.interactions.length ? ` Answers ${m.inputs.interactions.join(", ")}.` : "";
  const video = m.video && m.video !== "none" ? ` Video: ${m.video}.` : "";
  const overlay = m.transparent ? " Overlay." : "";
  const presets = m.presets.length ? ` Presets: ${m.presets.join(", ")}.` : "";
  return `- \`${m.id}\` (${kind}) ${m.description}${takes}${wordsIn}${answers}${video}${overlay}${presets} Tags: ${m.tags.join(", ")}.`;
}

/** The skill's effect index, file by file: a group's categories, each with its effects in catalog order. */
function effectIndex(metas: readonly EffectMeta[]): Map<string, string> {
  const files = new Map<string, string>();
  for (const group of EFFECT_CATEGORY_GROUPS) {
    const inGroup = metas.filter((m) => group.categories.includes(m.category));
    const sections = group.categories
      .map((category) => ({ category, effects: inGroup.filter((m) => m.category === category) }))
      .filter((c) => c.effects.length)
      .map((c) => `## ${c.category}\n\n${c.effects.map(indexLine).join("\n")}\n`);
    files.set(
      indexFile(group.name),
      [
        `# ${group.name}: ${inGroup.length} effect${inGroup.length === 1 ? "" : "s"}`,
        "",
        "<!-- Generated by `pnpm catalog:meta` from the catalog (src/catalog/lazy.test.ts): do not edit. -->",
        "",
        `Categories: ${group.categories.join(", ")}. Each line: \`id\` (kind) what it looks like, what it takes (a subject: image, video, svg, text, mask, path, audio), the text controls words go in, how it answers the pointer, how it suits video, whether it is an overlay, its presets and tags. Check an id before using it: \`flair effects --search <words>\` or \`getEffectMeta(id)\`.`,
        "",
        ...sections,
      ].join("\n"),
    );
  }
  return files;
}

function generate() {
  const modules = moduleOf();
  const packed = EFFECTS.map((e) => packMeta(metaOf(e, effectControls(e), effectInputs(e), effectDuration(e)), modules.get(e.id)!));
  const json = `[\n${packed.map((p) => JSON.stringify(p)).join(",\n")}\n]\n`;
  const keys = [...new Set(modules.values())].sort();
  const ts = [
    "// Generated by `pnpm catalog:meta` from the catalog (src/catalog/lazy.test.ts): do not edit.",
    "// Each catalog module that holds effects, loaded on demand by `loadEffect`.",
    "",
    "export const EFFECT_MODULES: Record<string, () => Promise<Record<string, unknown>>> = {",
    ...keys.map((k) => `  ${JSON.stringify(k)}: () => import("./${k}.js"),`),
    "};",
    "",
  ].join("\n");
  const layers = EFFECTS.filter((e) => e.kind !== "camera" && e.kind !== "timing").map((e) => {
    const inputs = effectInputs(e);
    return packLayerEntry({ id: e.id, kind: e.kind as "shader" | "vector", accepts: inputs.accepts, transition: inputs.video === "transition", transparent: e.kind === "shader" && !!e.transparent });
  });
  const index = [
    "// Generated by `pnpm catalog:meta` from the catalog (src/catalog/lazy.test.ts): do not edit.",
    "// Every shader and vector effect as `id:kind:inputs:flags` (see layer-index.ts), for checking scene layers.",
    "",
    `export const LAYER_INDEX = ${JSON.stringify(layers.join(" "))};`,
    "",
  ].join("\n");
  const effects = effectIndex(EFFECTS.map((e) => metaOf(e, effectControls(e), effectInputs(e), effectDuration(e))));
  return { json, ts, index, modules, packed, effects };
}

describe("the lazy catalog's generated files", () => {
  const generated = generate();

  it("find a module for every effect", () => {
    expect(EFFECTS.filter((e) => !generated.modules.has(e.id)).map((e) => e.id)).toEqual([]);
  });

  it("are up to date with the catalog (pnpm catalog:meta writes them)", () => {
    if (process.env.UPDATE_CATALOG_META) {
      writeFileSync(META_FILE, generated.json);
      writeFileSync(MODULES_FILE, generated.ts);
      writeFileSync(LAYERS_FILE, generated.index);
      rmSync(INDEX_DIR, { recursive: true, force: true });
      mkdirSync(INDEX_DIR, { recursive: true });
      for (const [file, text] of generated.effects) writeFileSync(resolve(INDEX_DIR, file), text);
    }
    expect(existsSync(META_FILE) && readFileSync(META_FILE, "utf8") === generated.json, "Run `pnpm catalog:meta`: the catalog has changed.").toBe(true);
    expect(existsSync(MODULES_FILE) && readFileSync(MODULES_FILE, "utf8") === generated.ts, "Run `pnpm catalog:meta`: the catalog has changed.").toBe(true);
    expect(existsSync(LAYERS_FILE) && readFileSync(LAYERS_FILE, "utf8") === generated.index, "Run `pnpm catalog:meta`: the catalog has changed.").toBe(true);
  });

  it("include the flair-use skill's effect index, up to date (pnpm catalog:meta writes it)", () => {
    const files = existsSync(INDEX_DIR) ? readdirSync(INDEX_DIR).sort() : [];
    expect(files, "Run `pnpm catalog:meta`: the effect index has other files than the catalog's groups.").toEqual([...generated.effects.keys()].sort());
    for (const [file, text] of generated.effects)
      expect(readFileSync(resolve(INDEX_DIR, file), "utf8") === text, `Run \`pnpm catalog:meta\`: skills/flair-use/references/effects/${file} is out of date.`).toBe(true);
    expect([...generated.effects.values()].join("").match(/^- `/gm)?.length).toBe(EFFECTS.length);
  });
});

describe("@pixerate/flair/catalog/lazy", async () => {
  const lazy = await import("./lazy.js");

  it("has every effect's metadata, in catalog order, with controls as the catalog has them", () => {
    expect(lazy.EFFECT_META.map((m) => m.id)).toEqual(EFFECTS.map((e) => e.id));
    for (const effect of EFFECTS) {
      const meta = lazy.getEffectMeta(effect.id)!;
      expect(meta).toEqual(metaOf(effect, effectControls(effect), effectInputs(effect), effectDuration(effect)));
      expect(meta.controls).toEqual(effectControls(effect));
    }
    expect(lazy.getEffectMeta("nope")).toBeUndefined();
  });

  it.each<[string, EffectQuery]>([
    ["everything", {}],
    ["words", { text: "fire" }],
    ["a category", { category: "glow" }],
    ["a group", { group: "Light" }],
    ["video filters", { video: ["filter"] }],
    ["transitions", { video: ["transition"] }],
    ["what takes text", { accepts: ["text"] }],
    ["what ignores the pointer", { interaction: [] }],
    ["overlays", { transparent: true }],
    ["single pictures", { singlePicture: true }],
    ["vector output", { output: "animation" }],
    ["video output", { output: "video", kind: "shader" }],
  ])("finds what findEffects finds: %s", (_, query) => {
    expect(lazy.findEffectMeta(query).map((m) => m.id)).toEqual(findEffects(query).map((e) => e.id));
  });

  it("lists the tags the catalog lists", () => {
    expect(lazy.effectTags()).toEqual(effectTags());
    expect(lazy.effectTags({ group: "Light", text: "neon" })).toEqual(effectTags({ group: "Light", text: "neon" }));
  });

  it.each(EFFECTS.map((e) => [e.id]))("loads %s", async (id) => {
    const effect = await lazy.loadEffect(id);
    expect(effect).toBe(getEffect(id));
    expect(lazy.getLoadedEffect(id)).toBe(effect);
  });

  it("loads each effect once, and several together", async () => {
    const [a, b, c, d] = await lazy.loadEffects(["aurora", "aurora", "transition-claw-slash", "transition-blood-wipe"]);
    expect(a).toBe(b);
    expect(await lazy.loadEffect("aurora")).toBe(a);
    expect(c).toBe(getEffect("transition-claw-slash"));
    expect(d).toBe(getEffect("transition-blood-wipe"));
  });

  it("refuses an unknown id, naming the nearest", async () => {
    await expect(lazy.loadEffect("auroa")).rejects.toThrow(/no effect "auroa".*Did you mean "aurora"/);
  });
});


describe("the full catalog's loadEffect and effectMeta", async () => {
  const full = await import("./index.js");

  it("load and describe as the lazy catalog does", async () => {
    const lazy = await import("./lazy.js");
    expect(await full.loadEffect("aurora")).toBe(getEffect("aurora"));
    expect(full.effectMeta(getEffect("aurora")!)).toEqual(lazy.getEffectMeta("aurora"));
    await expect(full.loadEffect("auroa")).rejects.toThrow(/Did you mean "aurora"/);
  });
});
